add_filter( 'woocommerce_order_actions', 'perfectpixel_duplicate_order_action' );
add_action( 'woocommerce_order_action_perfectpixel_duplicate', 'perfectpixel_duplicate_order' );

function perfectpixel_duplicate_order_action( $actions ) {
	$actions['perfectpixel_duplicate'] = 'Δημιουργία αντιγράφου παραγγελίας';
	return $actions;
}

function perfectpixel_duplicate_order( $order ) {
	$copy = wc_create_order(
		array(
			'customer_id' => $order->get_customer_id(),
			'created_via' => 'perfectpixel_duplicate',
		)
	);
	if ( is_wp_error( $copy ) ) {
		return;
	}
	$copy->set_address( $order->get_address( 'billing' ), 'billing' );
	$copy->set_address( $order->get_address( 'shipping' ), 'shipping' );
	$copy->set_currency( $order->get_currency() );
	$copy->set_prices_include_tax( $order->get_prices_include_tax() );
	$copy->set_customer_note( $order->get_customer_note() );

	foreach ( $order->get_items( array( 'line_item', 'shipping', 'fee' ) ) as $item ) {
		// A fresh item of the same class, so no database rows of the original are reused.
		$class = get_class( $item );
		$new   = new $class();
		$data  = $item->get_data();
		unset( $data['id'], $data['order_id'], $data['meta_data'] );
		$new->set_props( $data );
		foreach ( $item->get_meta_data() as $meta ) {
			$new->add_meta_data( $meta->key, $meta->value, false );
		}
		$copy->add_item( $new );
	}
	$copy->calculate_totals();
	$copy->set_status( 'pending' );
	$copy->add_order_note( sprintf( 'Αντίγραφο της παραγγελίας #%s.', $order->get_order_number() ) );
	$copy->save();

	$order->add_order_note( sprintf( 'Δημιουργήθηκε αντίγραφο: #%1$s (%2$s)', $copy->get_order_number(), $copy->get_edit_order_url() ) );
}
